for cx,cy,name in [(106,57,'gray'),(150,57,'brown'),(165,58,'orange'),(9,51,'pipe')]:
 print('\\n',name)
 for y in range(cy-15,cy+16):
  s=''
  for x in range(cx-16,cx+17):
   r,g,b=im[y,x]
   if name=='gray': v=(b-r>8 and b>70 and abs(int(g)-int(b))<20)
   elif name=='brown': v=(r>g*1.25 and b<70 and r>45)
   elif name=='orange': v=(r>g*1.15 and g>b*1.25 and r>130)
   else: v=(max(r,g,b)<55)
   s += '#' if v else '.'
  print(s)
